CREATE TABLE IF NOT EXISTS economy_transactions (id text PRIMARY KEY,guild_id text NOT NULL,user_id text NOT NULL,amount integer NOT NULL,type text NOT NULL,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS economy_items (id text PRIMARY KEY,guild_id text NOT NULL,name text NOT NULL,description text,price integer NOT NULL,stock integer NOT NULL DEFAULT -1,metadata jsonb);
CREATE TABLE IF NOT EXISTS cooldowns (guild_id text NOT NULL,user_id text NOT NULL,key text NOT NULL,expires_at timestamptz NOT NULL,UNIQUE(guild_id,user_id,key));
CREATE TABLE IF NOT EXISTS security_trusted (guild_id text NOT NULL,subject_id text NOT NULL,kind text NOT NULL,UNIQUE(guild_id,subject_id,kind));
CREATE TABLE IF NOT EXISTS security_events (id text PRIMARY KEY,guild_id text NOT NULL,type text NOT NULL,actor_id text,target_id text,severity text NOT NULL,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,user_id text NOT NULL,panel_id text,category_id text,claimed_by text,status text NOT NULL DEFAULT 'open',subject text,created_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz);
CREATE TABLE IF NOT EXISTS ticket_panels (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,category_id text,staff_role_id text,title text NOT NULL,description text,form jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transcripts (id text PRIMARY KEY,guild_id text NOT NULL,ticket_id text NOT NULL,content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS giveaways (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text,prize text NOT NULL,winner_count integer NOT NULL,ends_at timestamptz NOT NULL,requirements jsonb,status text NOT NULL DEFAULT 'running',winners jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS giveaway_entries (giveaway_id text NOT NULL,user_id text NOT NULL,entered_at timestamptz NOT NULL DEFAULT now(),UNIQUE(giveaway_id,user_id));
CREATE TABLE IF NOT EXISTS role_panels (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,title text NOT NULL,exclusive boolean NOT NULL DEFAULT false,roles jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS autoroles (guild_id text NOT NULL,role_id text NOT NULL,type text NOT NULL,UNIQUE(guild_id,role_id,type));
CREATE TABLE IF NOT EXISTS starboard (guild_id text NOT NULL,message_id text NOT NULL,channel_id text NOT NULL,star_message_id text,count integer NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(guild_id,message_id));
CREATE TABLE IF NOT EXISTS polls (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,question text NOT NULL,options jsonb NOT NULL,ends_at timestamptz,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS poll_votes (poll_id text NOT NULL,user_id text NOT NULL,option integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(poll_id,user_id));
CREATE TABLE IF NOT EXISTS suggestions (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,user_id text NOT NULL,content text NOT NULL,status text NOT NULL DEFAULT 'pending',staff_response text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suggestion_votes (suggestion_id text NOT NULL,user_id text NOT NULL,value integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(suggestion_id,user_id));
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text,title text NOT NULL,description text,starts_at timestamptz NOT NULL,timezone text NOT NULL DEFAULT 'UTC',status text NOT NULL DEFAULT 'scheduled',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_rsvps (event_id text NOT NULL,user_id text NOT NULL,status text NOT NULL DEFAULT 'going',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,user_id));
CREATE TABLE IF NOT EXISTS analytics (id text PRIMARY KEY,guild_id text NOT NULL,type text NOT NULL,user_id text,channel_id text,value integer NOT NULL DEFAULT 1,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS backups (id text PRIMARY KEY,guild_id text NOT NULL,actor_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS translations (id text PRIMARY KEY,guild_id text NOT NULL,source text NOT NULL,target text NOT NULL,provider text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_messages (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,user_id text NOT NULL,role text NOT NULL,content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
